See the License for the specific language governing permissions and
limitations under the License.
*/

package queue

import "time"

// QueueInterface defines the interface for both regular and priority queues.
type QueueInterface interface {
	// Put adds items to the queue.
	Put(items ...interface{}) error

	// Get retrieves items from the queue. If there are some items in the
	// queue, Get will return a number UP TO the number passed in as a
	// parameter. If no items are in the queue, this method will pause
	// until items are added to the queue.
	Get(number int64) ([]interface{}, error)

	// Empty returns a bool indicating if this queue is empty.
	Empty() bool

	// Len returns the number of items in this queue.
	Len() int64

	// Disposed returns a bool indicating if this queue
	// has had disposed called on it.
	Disposed() bool

	// Dispose will dispose of this queue and returns
	// the items disposed. Any subsequent calls to Get
	// or Put will return an error.
	Dispose() []interface{}
}

// PriorityQueueInterface defines the interface for priority queues.
type PriorityQueueInterface interface {
	// Put adds items to the priority queue.
	Put(items ...Item) error

	// Get retrieves items from the priority queue. If there are some items in the
	// queue, Get will return a number UP TO the number passed in as a
	// parameter. If no items are in the queue, this method will pause
	// until items are added to the queue.
	Get(number int) ([]Item, error)

	// Peek will look at the next item without removing it from the queue.
	Peek() Item

	// Empty returns a bool indicating if this priority queue is empty.
	Empty() bool

	// Len returns the number of items in this priority queue.
	Len() int

	// Disposed returns a bool indicating if this priority queue
	// has had disposed called on it.
	Disposed() bool

	// Dispose will dispose of this priority queue and returns
	// the items disposed. Any subsequent calls to Get
	// or Put will return an error.
	Dispose()
}
EOF
```

